/* P7.38.11: Decide freshness BEFORE any application initializer can write defaults.
   Other existing XenSonar data also blocks seeding: an untouched quick menu by
   itself is not evidence of a new browser. Storage failures are never 'fresh'. */
const __XenStarterColdBrowser=(()=>{
 try{return !Object.keys(localStorage).some(key=>/^xensonar(?:[.:-]|$)/i.test(key))}
 catch{return false}
})();

/* P7.38.11 · Both starters are ordinary v2 Meta Sessions (references + colors).
   Distinct Grid instance IDs preserve three different mute profiles in one rack.
   The underlying Drum, Bass and tuning libraries are not modified. */
const __XenStarterPrimaryId='built-in-starter-minor-worlds-v1';
const __XenStarterSecondaryId='built-in-starter-alternate-views-v1';
const __XenStarterPendingKey='xensonar.starter-demo-pending.v1';
const __XenStarterDemoIds=Object.freeze(['a','b','c'].map(letter=>'xensonar-starter-random-demo-'+letter+'-v1'));
function __xenStarterPresetRecords(){
 const modeMasks={
  '12edo|aeolian':[1,4,6,9,11],
  'ji|harmonic_minor':[3,5,8,9,10],
  'bp|bp_minor':[2,4,7,10],
  '19edo|phrygian':[1,3,4,6,7,9,10,12,14,15,17,18],
  '31edo|dorian':[1,2,3,4,6,7,9,10,11,12,14,15,16,17,19,20,21,22,24,25,27,28,29,30]
 };
 const profile=(id,name,instanceId,modeId)=>({kind:'grid',id,name,instanceId,
  gridProfile:{modeId,mainMutedDegrees:[...(modeMasks[id+'|'+modeId]??[])],mainStepOffsets:[],bassEnabled:false}});
 const entry=(kind,id,name)=>({kind,id,name});
 const initial=[
  profile('12edo','12 EDO · Aeolian','starter-grid-aeolian-12', 'aeolian'),
  // Native harmonic minor projects to JI ratios at indices [0,1,2,4,6,7,11].
  profile('ji','Just Intonation · Harmonic Minor','starter-grid-ji-harmonic','harmonic_minor'),
  profile('bp','Bohlen–Pierce · BP Moll','starter-grid-bp-minor','bp_minor'),
  entry('drum','preset:broken_lilt','Broken Lilt · Default'),
  entry('drum','preset:four_on_floor','Four on the Floor'),
  entry('drum','preset:forge_fractured','RhythmForge · Fractured'),
  entry('bass','preset:forge_fractured','RhythmForge · Fractured · Default'),
  entry('bass','preset:psy_classic','PsyBass · Classic Offbeat'),
  entry('bass','preset:psy_rolling','PsyBass · Rolling')];
 const alternate=[
  profile('19edo','19 EDO · Phrygian','starter-grid-19-phrygian','phrygian'),
  profile('31edo','31 EDO · Dorian','starter-grid-31-dorian','dorian'),
  entry('drum','preset:breakbeat','Breakbeat'),
  entry('drum','preset:minimal_techno','Minimal HiHat'),
  entry('bass','preset:psy_dark','PsyBass · Dark Forest'),
  entry('bass','preset:psy_gallop','PsyBass · Gallop')];
 // Primary: column-family backgrounds, individual border per tile.
 // Secondary: intentionally irregular, high-contrast color clashes, saved deterministically.
 const primaryPairs=[
  ['#83c5ed','#122d40'],['#b5f0d1','#122d40'],['#d5b6f1','#122d40'],
  ['#f5a167','#3b291e'],['#f0d080','#3b291e'],['#e9a0a5','#3b291e'],
  ['#8bd7ac','#17382d'],['#73d4d7','#17382d'],['#95b7e9','#17382d']];
 const secondaryPairs=[
  ['#e8ab54','#4a1d68'],['#ffb4d5','#115c57'],
  ['#82dbf4','#643016'],['#e2a1ff','#25427b'],
  ['#ffcc70','#4a611f'],['#a6f0a0','#6d294c']];
 const record=(id,name,items,pairs)=>({id,name,items,
  colors:Object.fromEntries(items.map((item,i)=>[__xenMetaColorKey(item),{border:pairs[i][0],background:pairs[i][1]}])),
  roomSettings:null});
 return {primary:record(__XenStarterPrimaryId,'01 · Three Minor Worlds',initial,primaryPairs),
  secondary:record(__XenStarterSecondaryId,'02 · Alternate Rhythms',alternate,secondaryPairs)};
}

/* Installer is private in intent, but uses exactly the same validation and
   transaction boundary as manually saved sessions. It never starts playback. */
repairStarterGridProfiles:()=>{
  const wanted=[...__xenStarterPresetRecords().primary.items,...__xenStarterPresetRecords().secondary.items].filter(x=>x.kind==='grid');
  const originals=new Map(wanted.map(x=>[x.instanceId,x]));
  const oldMutes={'starter-grid-ji-harmonic':[3,5,8,9,10]};
  const isLegacy=item=>{
    if(item?.kind!=='grid')return false;
    const next=originals.get(item.instanceId);
    if(!next||item.id!==next.id||!item.gridProfile)return false;
    const current=__xenGridProfile(item.gridProfile);
    const oldMode=item.instanceId==='starter-grid-ji-harmonic'?'chromatic':next.gridProfile.modeId;
    return current.modeId===oldMode&&current.mainMutedDegrees.join(',')===(oldMutes[item.instanceId]??[]).join(',')&&
      !current.mainStepOffsets.some(offset=>Math.abs(offset)>.02);
  };
  const eligible=state.saved.some(row=>[__XenStarterPrimaryId,__XenStarterSecondaryId].includes(row.id)&&row.items.some(isLegacy));
  if(!eligible)return false;
  return update(n=>{
    const fix=items=>{if(!Array.isArray(items))return;
      for(const item of items){if(!isLegacy(item))continue;
        const p=originals.get(item.instanceId).gridProfile;
        item.gridProfile={...item.gridProfile,modeId:p.modeId,mainMutedDegrees:[...p.mainMutedDegrees]};
      }
    };
    for(const row of n.saved)if([__XenStarterPrimaryId,__XenStarterSecondaryId].includes(row.id))fix(row.items);
    if([__XenStarterPrimaryId,__XenStarterSecondaryId].includes(n.loadedId)&&!n.dirty)fix(n.items);
    if([__XenStarterPrimaryId,__XenStarterSecondaryId].includes(n.activePalette?.id))fix(n.activePalette.items);
  });
},
installStarterPresets:(primary,secondary)=>update(n=>{
  if(n.saved.length||n.items.length||n.loadedId||n.activePalette)throw Error('Existing sessions are not starter-installable.');
  const base=validate(primary),alt=validate(secondary);
  if(!base||!alt)throw Error('Invalid starter sessions.');
  n.saved=[base,alt];n.items=clone(base.items);n.colors=clone(base.colors);
  n.name=base.name;n.roomSettings=null;n.loadedId=base.id;
  n.activePalette={id:base.id,name:base.name,items:clone(base.items),colors:clone(base.colors)};
  n.dirty=false;
},{reset:true}),
completeStarterDemo:demoRows=>{
  if(!Array.isArray(demoRows)||demoRows.length!==3||demoRows.some(r=>!r?.id||!r?.name))return false;
  if(!state.saved.some(row=>row.id===__XenStarterPrimaryId))return false;
  const additions=demoRows.flatMap(row=>[
    {kind:'material',id:row.id,name:row.name},
    {kind:'rootFollow',id:row.id,name:row.name}]);
  const quickBefore=quick.getItems(),base=__xenStarterPresetRecords().primary.items;
  const unchanged=quickBefore.length===base.length&&quickBefore.every((item,i)=>__xenGridKey(item)===__xenGridKey(base[i]));
  const activeIsStarter=state.activePalette?.id===__XenStarterPrimaryId;
  const colorsFor=additions=>Object.fromEntries(additions.map((entry,i)=>[
    __xenMetaColorKey(entry),{
     border:['#69d8df','#d2a0e8','#8be7ae','#e6b07a','#8dc4f2','#efa5a8'][i],
     background:entry.kind==='material'?'#1d344a':'#352940'}]));
  if(unchanged&&activeIsStarter)try{quick.replaceItems([...quickBefore,...additions])}catch{return false}
  const committed=update(n=>{
    const row=n.saved.find(x=>x.id===__XenStarterPrimaryId);
    if(!row)throw Error('Starter session was deleted.');
    row.items=__xenMetaValidateItems([...row.items,...additions]);
    row.colors={...row.colors,...colorsFor(additions)};
    if(n.loadedId===row.id&&!n.dirty){n.items=clone(row.items);n.colors=clone(row.colors)}
    if(unchanged&&activeIsStarter&&n.activePalette?.id===row.id){
     n.activePalette={id:row.id,name:row.name,items:clone(row.items),colors:clone(row.colors)};
    }
  });
  if(!committed&&unchanged&&activeIsStarter)try{quick.replaceItems(quickBefore)}catch{}
  return committed;
},

/* Bulk visual edit, scoped to the editor draft. One atomic store write and one Undo.
   Unselected channel is copied untouched, including an unset/default channel. */
setGlobalColor:(mode,value)=>update(n=>{
  if(!['border','background','both'].includes(mode))throw Error('Unknown global color mode.');
  if(!n.items.length)throw Error('The session has no entries to recolor.');
  const raw=mode==='both'?value:{[mode]:value};
  if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Invalid global color input.');
  const changes={};
  for(const channel of mode==='both'?['border','background']:[mode]){
    const hex=__xenMetaHex(raw[channel]);
    if(!hex)throw Error('Global '+channel+' must be a #RRGGBB color.');
    changes[channel]=hex;
  }
  for(const entry of n.items){const key=__xenMetaColorKey(entry);n.colors[key]={...(n.colors[key]??{}),...changes}}
  mark(n);
},{record:true}),

/* Cold boot installs lightweight session metadata first. Audio is rendered later
   on idle, serially, through the existing Melodic Loop renderer and Material
   package bridge; only three WAVs are stored, shared by Material and RFL. */
const __XenStarterQuickRepaired=(()=>{
 try{
  const old=__XenQuick.getItems(),reference=[...__xenStarterPresetRecords().primary.items,...__xenStarterPresetRecords().secondary.items];
  let changed=false;
  const next=old.map(item=>{
   const standard=reference.find(x=>x.kind==='grid'&&x.instanceId===item.instanceId&&x.id===item.id);
   if(!standard||!item.gridProfile)return item;
   const p=item.gridProfile,legacyMode=item.instanceId==='starter-grid-ji-harmonic'?'chromatic':standard.gridProfile.modeId;
   const legacyMask=item.instanceId==='starter-grid-ji-harmonic'?[3,5,8,9,10]:[];
   if(p.modeId!==legacyMode||JSON.stringify(p.mainMutedDegrees??[])!==JSON.stringify(legacyMask)||
    (p.mainStepOffsets??[]).some(x=>Math.abs(x)>.02))return item;
   changed=true;
   return {...item,gridProfile:{...p,modeId:standard.gridProfile.modeId,
     mainMutedDegrees:[...standard.gridProfile.mainMutedDegrees]}};
  });
  if(changed)__XenQuick.replaceItems(next);
  return changed;
 }catch(error){console.warn('[xensonar][starter-sessions] Quickrack profile upgrade failed:',error);return false}
})();
const __XenStarterProfilesRepaired=(()=>{
 try{return __XenMetaSessions.repairStarterGridProfiles()}catch(error){
  console.warn('[xensonar][starter-sessions] Existing starter profile upgrade failed:',error);return false
 }
})();
const __XenStarterInstalled=(()=>{
 if(!__XenStarterColdBrowser)return false;
 try{
  if(localStorage.getItem(__XenMetaSessions.key)!==null||localStorage.getItem('xensonar.quick-menu.v2')!==null||localStorage.getItem('xensonar.quick-menu.v1')!==null)return false;
  const {primary,secondary}=__xenStarterPresetRecords();
  __XenQuick.replaceItems(primary.items);
  if(!__XenMetaSessions.installStarterPresets(primary,secondary)){
   __XenQuick.replaceItems([]);return false;
  }
  localStorage.setItem(__XenStarterPendingKey,'pending');
  return true;
 }catch(error){console.warn('[xensonar][starter-sessions] Unable to install:',error);return false}
})();

